-- Check if --use-conan flag is set
local useConan = _OPTIONS["use-conan"] ~= nil

-- Load Conan-generated dependencies only when --use-conan flag is set
-- Note: This file is dofile'd from premake5.lua, so paths are relative to project root
local project_root = path.getdirectory(_SCRIPT) .. "/.."
if useConan then
    local conan_deps_path = project_root .. '/_build/generated/conan-deps/conandeps.premake5.lua'
    if os.isfile(conan_deps_path) then
        dofile(conan_deps_path)
        -- Include conan wrapper functions to fix parameter handling bugs
        dofile(project_root .. '/tools/conan-wrappers.lua')
        print("Note: Using Conan packages (--use-conan flag set)")
    else
        error("--use-conan flag set but Conan deps not found at " .. conan_deps_path .. ". Run conan install first.")
    end
else
    print("Note: Using Packman packages (no --use-conan flag)")
end

-- Include and statically link zlib to a project.
-- When --use-conan is set, zlib is provided by Conan (see conanfile.py)
-- Otherwise, zlib is provided by Packman (see deps/rtx-target-deps.packman.xml)
function add_zlib()
    if useConan then
        -- Use Conan-provided zlib
        if not conandeps then
            error("add_zlib() with --use-conan requires Conan deps. Ensure conan install was run before premake generation.")
        end
        filter { "system:windows" }
            -- Disable GCC-specific visibility attributes on MSVC (must be BEFORE conan_setup)
            defines { "ZEXTERN=extern" }
            conan_setup(nil, "zlib")
        filter { "system:linux" }
            conan_setup(nil, "zlib")
        filter {}
    else
        -- Use Packman-provided zlib
        filter { "system:windows" }
            defines { "ZEXTERN=extern" }
            externalincludedirs { "%{root}/_build/target-deps/zlib/include" }
            libdirs { "%{root}/_build/target-deps/zlib/lib" }
            links { "zlib" }
        filter { "system:linux" }
            externalincludedirs { "%{root}/_build/target-deps/zlib/include" }
            libdirs { "%{root}/_build/target-deps/zlib/lib" }
            links { "z" }
        filter {}
    end
end
